import type { Core } from '@strapi/strapi';
import { seedAdmin } from './seed/admin';
import { seedCountries } from './seed/countries';
import { grantPublicPermissions } from './seed/permissions';

export default {
  register() {},

  // Idempotent: safe to run on every start.
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    await grantPublicPermissions(strapi);
    await seedCountries(strapi);
    await seedAdmin(strapi);
  },
};
import type { Core } from '@strapi/strapi';

export async function seedAdmin(strapi: Core.Strapi): Promise<void> {
  const email = process.env.ADMIN_EMAIL;
  const password = process.env.ADMIN_PASSWORD;
  if (!email || !password) return;

  const existing = await strapi.db.query('admin::user').count({});
  if (existing > 0) return;

  const superAdminRole = await strapi.db.query('admin::role').findOne({ where: { code: 'strapi-super-admin' } });
  if (!superAdminRole) return;

  const hashedPassword = await strapi.service('admin::auth').hashPassword(password);
  await strapi.db.query('admin::user').create({
    data: {
      email,
      firstname: 'Admin',
      lastname: 'User',
      password: hashedPassword,
      isActive: true,
      blocked: false,
      roles: [superAdminRole.id],
    },
  });
  strapi.log.info(`Seed: created admin user ${email}`);
}
import fs from 'node:fs';
import path from 'node:path';
import type { Core } from '@strapi/strapi';

const UID = 'api::country.country';

interface SeedCountry {
  code: string;
  name: string;
  order: number;
  active: boolean;
  icon?: { file: string; alt: string };
}

// Fictitious demo data. PE is inactive on purpose to demo FR-006.
const COUNTRIES: SeedCountry[] = [
  { code: 'CO', name: 'Colombia', order: 1, active: true, icon: { file: 'co.svg', alt: 'Bandera de Colombia' } },
  { code: 'CL', name: 'Chile', order: 2, active: true, icon: { file: 'cl.svg', alt: 'Bandera de Chile' } },
  { code: 'PE', name: 'Perú', order: 3, active: false },
];

async function uploadIcon(strapi: Core.Strapi, file: string, alt: string): Promise<number> {
  // Read from src/ (not dist/) so the SVGs do not need a build copy step.
  const filepath = path.join(strapi.dirs.app.root, 'src', 'seed', 'assets', file);
  const { size } = fs.statSync(filepath);
  const [uploaded] = await strapi.plugin('upload').service('upload').upload({
    data: { fileInfo: { name: file, alternativeText: alt, caption: alt } },
    files: { filepath, originalFilename: file, mimetype: 'image/svg+xml', size },
  });
  return uploaded.id;
}

export async function seedCountries(strapi: Core.Strapi): Promise<void> {
  const total = await strapi.documents(UID).count({});
  if (total > 0) return;

  for (const country of COUNTRIES) {
    const icon = country.icon ? await uploadIcon(strapi, country.icon.file, country.icon.alt) : undefined;
    await strapi.documents(UID).create({
      data: { code: country.code, name: country.name, order: country.order, active: country.active, icon },
      status: 'published',
    });
  }
}
import type { Core } from '@strapi/strapi';

// Actions the Public role needs, each with the reason it is granted.
const PUBLIC_ACTIONS = [
  // The wizard reads the list of available countries (US-00).
  'api::country.country.find',
];

export async function grantPublicPermissions(strapi: Core.Strapi): Promise<void> {
  const role = await strapi.db.query('plugin::users-permissions.role').findOne({ where: { type: 'public' } });
  if (!role) return;

  for (const action of PUBLIC_ACTIONS) {
    const existing = await strapi.db
      .query('plugin::users-permissions.permission')
      .findOne({ where: { action, role: role.id } });
    if (!existing) {
      await strapi.db.query('plugin::users-permissions.permission').create({ data: { action, role: role.id } });
    }
  }
}
import { factories } from '@strapi/strapi';

export default factories.createCoreController('api::country.country', ({ strapi }) => ({
  // Only active countries are ever exposed (research R1). The client cannot override this:
  // its own filters are kept but combined with `active = true` through $and. `status` is forced
  // to 'published' so `?status=draft` cannot leak unpublished countries (R1, ADR 0001).
  async find(ctx) {
    const clientFilters = (ctx.query as Record<string, unknown>).filters;
    ctx.query = {
      ...ctx.query,
      status: 'published',
      filters: clientFilters ? { $and: [{ active: true }, clientFilters] } : { active: true },
    };
    return super.find(ctx);
  },
}));
{
  "kind": "collectionType",
  "collectionName": "countries",
  "info": {
    "singularName": "country",
    "pluralName": "countries",
    "displayName": "Country",
    "description": "Country available in the quote wizard"
  },
  "options": { "draftAndPublish": true },
  "pluginOptions": {},
  "attributes": {
    "name": { "type": "string", "required": true },
    "code": { "type": "string", "required": true, "unique": true, "regex": "^[A-Z]{2}$" },
    "icon": { "type": "media", "multiple": false, "required": false, "allowedTypes": ["images"] },
    "order": { "type": "integer", "required": true, "min": 1 },
    "active": { "type": "boolean", "required": true, "default": true }
  }
}
